// ?bfmeSetState1285@BfmeNode1285@@QAEXH@Z
// partial score=0.4646 date=2026-09-29
// cl: /O2 /DNDEBUG /DWIN32 /D_WINDOWS /MD
//
// 126 bytes against retail 127. This is the closest STRUCTURAL candidate found
// for this body: 0.982 of instructions match once registers are normalised and
// only TWO instructions differ, both in one adjacent pair:
//
//   +0035  retail  mov edx, dword ptr [ecx + 0x30]   ours  mov eax, ...
//   +003b  retail  lea eax, [edx + ebp]              ours  add eax, ebp
//
// Everything from +0x3e to the epilogue is byte-identical to retail: the whole
// 12-argument submit block, the loop-bottom descriptor/count reload, the
// register-pop tail and `ret 4`. The prologue, the state guard, the
// bfmeReset1285 call and the loop latch are exact too. The earlier banked body
// (attempt_history 33ecf230...) was worse: it put the descriptor in edx, the
// records pointer in eax, and rotated every submit argument after it, for three
// structural breaks rather than one.
//
// The residue is a single compiler decision, and it is the same decision
// everywhere it has been probed: MSVC plans the address as `add base, offset`,
// so the records load is coalesced into the add's destination register (eax,
// the natural home for a loaded value) and the base dies there. Retail keeps
// the base in edx and builds the address into a fresh eax, spending one extra
// byte. Per targets/game/reverse/analysis/sib_lea_experiments.md, MSVC 7.1
// picks that 2-operand form unless both addends are live past the combination.
//
// RULED OUT for this pair, all measured this session and in the three prior
// sessions on this body (about 1300 compiles in build/experiments.sqlite):
//
//  * member kind: pointer, array [1], pointer-to-array [1];
//  * volatile on the DESCRIPTOR pointer (this is what pins the +0x32 reload in
//    ecx, so it is load-bearing, not decoration), on the RECORDS pointer
//    object, and on the records pointee -- the last is the only construct that
//    forbids folding the load into the addressing mode while leaving the value
//    register-resident, and it still emits the 2-operand add;
//  * dropping the hand-written byte offset entirely, so the ebp IV is MSVC's
//    own strength reduction of base[index] with stride 0x44 -- retail's latch
//    is `inc edi` AND `add ebp,0x44`, which is what that reduction emits, and
//    it is the most likely native spelling. It measures 126 with the same pair;
//  * record expression: &base[i], base + i, (char*)base + offset, (char*)base +
//    index*0x44, offset on the left, unsigned/long offset, register-qualified,
//    const-qualified, a reference, an alias taken twice, a two-statement walk
//    (char *walk; walk += offset;), and a live base used a second time;
//  * barrier layout: zero through four, and every position around the records
//    load, the state read and the mask test. Two barriers are required for the
//    +0x32 reload and the `test dword ptr [eax],ecx`; a third between the
//    records load and the add rotates the whole allocation to 128;
//  * loop form (do-while vs for), tools/rotation_sweep.py (9 toggles, no byte
//    progress), tools/shape_family_levers.py over all ten families (1 choice,
//    the commutative TEST operand order, which measures 126 unchanged).
//
// The array-member form is the informative negative: it produces the right
// 3-operand `lea eax,[ecx+ebp+0x30]` with every register matching, but folds
// the base load into the SIB displacement, which proves retail's `mov
// edx,[ecx+0x30]` really is a pointer member. Asking for both halves at once --
// a materialised base AND a three-operand lea -- is what MSVC 7.1 declines.
//
// CODGEN LEVERS, not semantics: the volatile qualifier on m_descriptor and the
// two _ReadWriteBarrier calls exist only to pin the loop-top reloads. A plain
// read of m_descriptor gives edx at +0x32, and a volatile-qualified LOCAL
// spills to the stack (134 bytes).
//
// IDENTITY: the 0x008BB570 matched caller names this symbol, and the state-slot
// layout agrees with it (descriptor at +0x0c, count +0x2c, records +0x30,
// state +0x1c, submitter +0x20).

extern "C" void _ReadWriteBarrier( void );
#pragma intrinsic( _ReadWriteBarrier )

class BfmeStateSlot1285
{
public:
	void bfmeReset1285( int value );
};

struct BfmeStateRecord1285
{
	int m_mask;                          // +0x00, tested against m_state
	int m_value;                         // +0x04, third submit argument
	int m_gap08;
	float m_weight;                      // +0x0c, ninth submit argument
	char m_gap10[ 0x24 - 0x10 ];
	float m_tail;                        // +0x24, eighth (PAM) submit argument
	char m_gap28[ 0x44 - 0x28 ];
};

struct BfmeStateDescriptor1285
{
	char m_gap00[ 0x2c ];
	int m_count;                         // +0x2c, loop bound, re-read each pass
	BfmeStateRecord1285 *m_records;      // +0x30, stride 0x44
};

struct BfmeNodeState1285
{
	char m_gap00[ 0x0c ];
	volatile BfmeStateDescriptor1285 *m_descriptor;
	char m_gap10[ 0x1c - 0x10 ];
	int m_state;                         // +0x1c
	BfmeStateSlot1285 m_slot;            // +0x20
};

class BfmeSubmitter1283
{
public:
	void bfmeSubmit1283( int a0, int a1, int a2, int a3, int a4, int a5,
		int a6, float *weight, int a8, int a9, int a10, int a11 );
};

class BfmeNode1285
{
public:
	void bfmeSetState1285( int state );

private:
	char m_gap00[ 0x50 ];
	BfmeNodeState1285 *m_info;
};

void BfmeNode1285::bfmeSetState1285( int state )
{
	BfmeNodeState1285 *info = m_info;
	if ( state == info->m_state )
		return;

	BfmeSubmitter1283 *submitter = (BfmeSubmitter1283 *)&info->m_slot;
	int offset;
	info->m_state = state;
	info->m_slot.bfmeReset1285( 0 );

	int index = 0;
	if ( info->m_descriptor->m_count > 0 )
	{
		offset = 0;
		do
		{
			_ReadWriteBarrier();
			BfmeStateRecord1285 *record = (BfmeStateRecord1285 *)
				((char *)info->m_descriptor->m_records + offset);
			int currentState = info->m_state;
			_ReadWriteBarrier();
			if ( (record->m_mask & currentState) != 0 )
			{
				submitter->bfmeSubmit1283(
					0, index, record->m_value, 0, (int)this, 0,
					-1, &record->m_tail, (int)&record->m_weight, 0, 0, 0 );
			}
			++index;
			offset += 0x44;
		} while ( index < info->m_descriptor->m_count );
	}
}
